#include <stdio.h>
#include <stdlib.h>

/* Declared identically in solution.c -- separate translation units, same
   layout, which is exactly what a shared header would give you. */
struct node {
    int value;
    struct node *next;
};

/* Provided by the candidate in solution.c */
struct node *reverse_list(struct node *head);

static void free_list(struct node *head)
{
    while (head != NULL) {
        struct node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    int count;
    if (scanf("%d", &count) != 1 || count < 0) {
        return 1;
    }

    struct node *head = NULL;
    struct node *tail = NULL;
    for (int i = 0; i < count; i++) {
        int value;
        if (scanf("%d", &value) != 1) {
            free_list(head);
            return 1;
        }
        struct node *fresh = malloc(sizeof *fresh);
        if (fresh == NULL) {
            free_list(head);
            return 1;
        }
        fresh->value = value;
        fresh->next = NULL;
        if (tail == NULL) {
            head = fresh;
        } else {
            tail->next = fresh;
        }
        tail = fresh;
    }

    head = reverse_list(head);

    for (struct node *walk = head; walk != NULL; walk = walk->next) {
        printf("%d%s", walk->value, (walk->next != NULL) ? " " : "");
    }
    printf("\n");

    free_list(head);
    return 0;
}

