"""Random lists to reverse.

The harness builds the nodes from these values in the order given, so a case
is just a list of numbers. Lengths are kept short: a pointer bug shows up at
three nodes exactly as clearly as at three hundred, and a shorter expected
line is a great deal easier to read when it goes wrong.
"""


def generate(rng, count):
    builders = (_short, _medium, _with_repeats, _longer)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n" % (len(values), " ".join(str(v) for v in values)),
        "description": description,
    }


def _short(rng, index):
    return _case("three nodes #%d" % index,
                 [rng.randint(-99, 99) for _ in range(3)])


def _medium(rng, index):
    return _case("a handful of nodes #%d" % index,
                 [rng.randint(-99, 99) for _ in range(rng.randint(4, 7))])


def _with_repeats(rng, index):
    value = rng.randint(-50, 50)
    values = [value] * rng.randint(2, 4) + [rng.randint(-99, 99)
                                            for _ in range(rng.randint(1, 3))]
    rng.shuffle(values)
    return _case("repeated values #%d" % index, values,
                 "Equal values in different nodes. What is being reversed is "
                 "the links, not the numbers.")


def _longer(rng, index):
    return _case("a longer list #%d" % index,
                 [rng.randint(-99, 99) for _ in range(rng.randint(8, 12))])
